def resolve(path, cwd, links):
    # Normalize input path
    if not path.startswith('/'):
        path = cwd + '/' + path

    # Split path into components
    components = path.split('/')

    # Initialize result as empty list and track symlink count
    result = []
    symlink_count = 0
    max_symlinks = 8

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if result:
                result.pop()
            continue

        # Append the component
        result.append(component)

        # Check if the current path is a symlink
        current_path = '/' + '/'.join(result)

        while current_path in links:
            # Check symlink limit
            symlink_count += 1
            if symlink_count > max_symlinks:
                return None

            # Get the target of the symlink
            target = links[current_path]

            # If target is absolute, start from root; otherwise relative to parent
            if target.startswith('/'):
                result = []
                target_components = target.split('/')
            else:
                # Remove the last component (the symlink itself) to get parent dir
                result.pop()
                target_components = target.split('/')

            # Process target components
            for target_comp in target_components:
                if target_comp == '' or target_comp == '.':
                    continue

                if target_comp == '..':
                    if result:
                        result.pop()
                    continue

                result.append(target_comp)
                current_path = '/' + '/'.join(result)

                # Check again if we hit another symlink (for chains)
                if current_path in links:
                    break

            # After processing target, check if current_path is a symlink
            if current_path not in links:
                break

    # Build the final path
    if not result:
        return '/'

    return '/' + '/'.join(result)

